function nodeEditor(node, index, list = []) {
  const options = nodeOptions(list.length ? list : [node], "");
  return `<article class="graph-node graph-node-${attr(node.type)}" data-graph-node>
    <div class="graph-node-head"><strong>${text(node.label || node.id)}</strong><button type="button" data-graph-action="delete:${attr(node.id)}">Delete</button></div>
    <div class="graph-node-grid">
      ${nodeInput("id", "ID", node.id)}
      ${nodeSelect("type", "Type", node.type, ["condition", "send", "archive", "stop"])}
      ${nodeInput("label", "Label", node.label)}
      ${nodeInput("archiveTag", "Archive tag", node.archiveTag)}
      ${nodeInput("match", node.regex ? "Regex" : "Contains text", node.match)}
      ${nodeCheckbox("regex", "Use regex", node.regex)}
      ${nodeInput("flags", "Regex flags", node.flags || "i")}
      ${nodeCheckbox("negate", "Negate condition", node.negate)}
      ${nodeSelect("onTrue", "On true", node.onTrue, ["", ...list.map(n => n.id)])}
      ${nodeSelect("onFalse", "On false", node.onFalse, ["", ...list.map(n => n.id)])}
      ${nodeSelect("next", "Next", node.next, ["", ...list.map(n => n.id)])}
    </div>
    <label class="automation-field graph-node-prompt">Prompt<textarea data-node-field="prompt" rows="4">${text(node.prompt || "")}</textarea></label>
    <p>${text(describeNode(node))}</p>
  </article>`;
}
function describeNode(node) { if (node.type === "condition") return `${node.negate ? "unless" : "if"} last message contains "${node.match}" → ${node.onTrue || "?"} / ${node.onFalse || "?"}`; if (node.type === "send") return `send: ${node.prompt || "settings prompt"}`; if (node.type === "archive") return `archive as ${node.archiveTag || node.id} then ${node.next || "stop"}`; return "stop"; }
function nodeInput(name, labelText, value = "") { return `<label class="automation-field">${labelText}<input data-node-field="${name}" value="${attr(value)}"></label>`; }
function nodeCheckbox(name, labelText, value = false) { return `<label class="automation-field"><input data-node-field="${name}" type="checkbox" ${value ? "checked" : ""}> ${labelText}</label>`; }
function nodeSelect(name, labelText, value, values) { return `<label class="automation-field">${labelText}<select data-node-field="${name}">${values.map(item => `<option value="${attr(item)}" ${item === value ? "selected" : ""}>${text(item || "—")}</option>`).join("")}</select></label>`; }
function nodeOptions(nodes = [], selected = "") { return nodes.map(node => `<option value="${attr(node.id)}" ${node.id === selected ? "selected" : ""}>${text(node.label || node.id)}</option>`).join(""); }
function newNode(type, index) { const id = `${type}-${index + 1}`; return { id, type, label: `${type} ${index + 1}`, match: "", negate: false, prompt: type === "send" ? "continue with the next precise verified step" : "", archiveTag: type === "archive" || type === "send" ? "graph" : "", onTrue: "", onFalse: "", next: "" }; }
function tab(name, labelText, active) { return `<button type="button" data-tab="${name}" class="${active === name ? "active" : ""}">${labelText}</button>`; }
function field(name, labelText, type, value) { const checked = type === "checkbox" && value ? "checked" : ""; const val = type === "checkbox" ? "" : `value="${attr(value)}"`; return `<label class="automation-field">${labelText}<input data-auto="${name}" type="${type}" ${val} ${checked}></label>`; }
function cast(value) { return /^\d+$/.test(String(value)) ? Number(value) : value; }
function attr(value) { return String(value ?? "").replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }
function text(value) { return String(value ?? "").replace(/[&<>]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c])); }
function label(type) { return ({ awtsmoos_tool: "Awtsmoos tool calls", agent_tool: "Agent tool calls", tool_call: "Generic tool calls", tool_result: "Tool results", status: "Status packets", raw: "Raw packets", hidden: "Hidden messages", code: "Code payloads", thinking: "Thinking traces", oauth: "OAuth prompts" })[type] || type.replace(/_/g, " "); }
